class Solution {
  private static int[] bfs(int n, int[] head, int[] next, int[] to, int src) {
    int[] dist = new int[n];
    java.util.Arrays.fill(dist, -1);
    int[] queue = new int[n];
    int qh = 0, qt = 0;
    queue[qt++] = src;
    dist[src] = 0;
    while (qh < qt) {
      int u = queue[qh++];
      for (int e = head[u]; e >= 0; e = next[e]) {
        if (dist[to[e]] < 0) {
          dist[to[e]] = dist[u] + 1;
          queue[qt++] = to[e];
        }
      }
    }
    return dist;
  }

  public int specialNodes(int n, int[][] edges, int x, int y, int z) {
    int[] head = new int[n], next = new int[2 * (n - 1)], to = new int[2 * (n - 1)];
    java.util.Arrays.fill(head, -1);
    int cnt = 0;
    for (int[] e : edges) {
      to[cnt] = e[1];
      next[cnt] = head[e[0]];
      head[e[0]] = cnt++;
      to[cnt] = e[0];
      next[cnt] = head[e[1]];
      head[e[1]] = cnt++;
    }
    int[] dx = bfs(n, head, next, to, x),
        dy = bfs(n, head, next, to, y),
        dz = bfs(n, head, next, to, z);
    int special = 0;
    for (int u = 0; u < n; u++) {
      long a = dx[u], b = dy[u], c = dz[u];
      long max = Math.max(a, Math.max(b, c));
      long sumSquares = a * a + b * b + c * c;
      if (sumSquares == 2 * max * max) special++;
    }
    return special;
  }
}
